:root{
  --blue:#0088C0; --teal:#00A890; --grey:#888888; --deep:#0A3A52;
  --ink:#123647; --body:#2E4750; --muted:#5B7079;
  --line:#D7E4EA; --tint:#EAF6FB; --tint2:#E7F7F2; --sand:#F7FAFB; --white:#fff;
  --link:#0A6E9B; --action:#0A3A52; --action-h:#0088C0;
  --radius:16px; --radius-sm:10px; --shadow:0 10px 30px rgba(10,58,82,.10); --shadow-sm:0 4px 14px rgba(10,58,82,.08);
  --wrap:1160px; --gap:clamp(20px,4vw,48px);
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,"Noto Sans",sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:var(--body);background:var(--white);line-height:1.65;font-size:17px;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{color:var(--ink);line-height:1.18;margin:0 0 .5em;font-weight:800;letter-spacing:-.01em}
h1{font-size:clamp(2rem,4.4vw,3.05rem)}
h2{font-size:clamp(1.55rem,3vw,2.2rem)}
h3{font-size:1.2rem;font-weight:750}
p{margin:0 0 1rem}
a{color:var(--link);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.sec{padding:clamp(44px,6vw,78px) 0}
.eyebrow{display:inline-block;font-size:.82rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--teal);margin-bottom:.7rem}
.lead{font-size:1.12rem;color:var(--muted)}
.center{text-align:center}
.maxw{max-width:760px}
.maxw.center{margin-left:auto;margin-right:auto}

/* skip link + focus */
.skip{position:absolute;left:-999px;top:0;background:var(--deep);color:#fff;padding:12px 18px;z-index:200;border-radius:0 0 10px 0}
.skip:focus{left:0}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:2px;border-radius:4px}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:.55em;font-weight:750;font-size:1rem;padding:.9em 1.5em;border-radius:999px;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,background .15s ease,box-shadow .15s ease;text-decoration:none}
.btn:hover{text-decoration:none;transform:translateY(-2px)}
.btn-primary{background:var(--action);color:#fff;box-shadow:var(--shadow-sm)}
.btn-primary:hover{background:var(--action-h);color:#fff}
.btn-ghost{background:transparent;color:var(--deep);border-color:var(--line)}
.btn-ghost:hover{border-color:var(--blue);color:var(--blue)}
.btn-white{background:#fff;color:var(--deep)}
.btn-white:hover{background:#eaf6fb;color:var(--deep)}
.btn-lg{font-size:1.06rem;padding:1.02em 1.7em}

/* header */
.site-head{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:saturate(1.1) blur(6px);border-bottom:1px solid var(--line)}
.util{background:var(--deep);color:#dfeef5;font-size:.86rem}
.util .wrap{display:flex;gap:18px;align-items:center;justify-content:space-between;padding:7px 22px;flex-wrap:wrap}
.util a{color:#fff;font-weight:700}
.util .util-r{display:flex;gap:18px;align-items:center;flex-wrap:wrap}
.util i{color:var(--teal);margin-right:.4em}
.nav{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 22px;max-width:var(--wrap);margin:0 auto}
.brand{display:flex;align-items:center}
.brand img{height:52px;width:auto}
.menu{display:flex;gap:26px;align-items:center;list-style:none;margin:0;padding:0}
.menu > li{position:relative}
.menu a{color:var(--ink);font-weight:700;font-size:.98rem;padding:8px 2px}
.menu a:hover{color:var(--blue);text-decoration:none}
.has-sub > a::after{content:"\f078";font-family:"Font Awesome 6 Free";font-weight:900;font-size:.62rem;margin-left:.45em;color:var(--grey)}
.sub{position:absolute;top:100%;left:0;min-width:250px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);padding:8px;opacity:0;visibility:hidden;transform:translateY(8px);transition:.16s;list-style:none;margin:8px 0 0}
.menu li:hover > .sub,.menu li:focus-within > .sub{opacity:1;visibility:visible;transform:translateY(0)}
.sub a{display:block;padding:9px 12px;border-radius:8px;font-size:.94rem}
.sub a:hover{background:var(--tint)}
.nav-cta{display:flex;gap:12px;align-items:center}
.burger{display:none;background:none;border:0;font-size:1.5rem;color:var(--deep);cursor:pointer}

/* hero */
.hero{position:relative;background:var(--deep);color:#eaf6fb;overflow:hidden}
.hero::before{content:"";position:absolute;inset:0;background:
  radial-gradient(1100px 480px at 82% -10%,rgba(0,168,144,.42),transparent 60%),
  radial-gradient(900px 520px at 8% 108%,rgba(0,136,192,.42),transparent 60%)}
.hero-grid{position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:44px;align-items:center;padding:clamp(40px,5vw,68px) 0}
.hero h1{color:#fff}
.hero .lead{color:#cfe6f1}
.hero-chips{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 26px}
.hchip{display:inline-flex;align-items:center;gap:.5em;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);color:#eaf6fb;padding:.5em .9em;border-radius:999px;font-size:.88rem;font-weight:650}
.hchip i{color:var(--teal)}
.hero-actions{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.hero-actions .tel{color:#fff;font-weight:800;font-size:1.05rem;display:inline-flex;gap:.5em;align-items:center}
.hero-actions .tel i{color:var(--teal)}

/* form card */
.formcard{background:#fff;color:var(--body);border-radius:20px;box-shadow:0 24px 60px rgba(3,26,38,.35);padding:26px}
.formcard h2{font-size:1.32rem;margin-bottom:.25em}
.formcard .fnote{font-size:.9rem;color:var(--muted);margin-bottom:1rem}
.field{margin-bottom:12px}
.field label{display:block;font-weight:700;font-size:.9rem;color:var(--ink);margin-bottom:5px}
.field input,.field select,.field textarea{width:100%;padding:12px 13px;border:1.5px solid var(--line);border-radius:10px;font:inherit;font-size:.98rem;background:#fdfefe;color:var(--body)}
.field textarea{min-height:86px;resize:vertical}
.hp{position:absolute;left:-9999px}
.form-msg{display:none;margin-top:10px;padding:11px 13px;border-radius:10px;font-size:.92rem;background:var(--tint2);border:1px solid var(--teal);color:#0b5a4c}

/* trust bar */
.trustbar{background:var(--deep);color:#eaf6fb}
.trustbar .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;padding:26px 22px}
.tb-item{display:flex;gap:12px;align-items:flex-start}
.tb-item i{color:var(--teal);font-size:1.35rem;margin-top:3px}
.tb-item strong{display:block;color:#fff;font-size:.98rem}
.tb-item span{font-size:.86rem;color:#bcd7e3}

/* generic grids + cards */
.grid{display:grid;gap:22px}
.g2{grid-template-columns:repeat(2,1fr)}
.g3{grid-template-columns:repeat(3,1fr)}
.g4{grid-template-columns:repeat(4,1fr)}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm)}
.ictile{width:52px;height:52px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,var(--blue),var(--teal));color:#fff;font-size:1.25rem;margin-bottom:14px}
.ictile.alt{background:linear-gradient(135deg,var(--deep),var(--blue))}

/* service cards */
.svc{display:block;background:#fff;border:1px solid var(--line);border-top:4px solid var(--teal);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);color:var(--body);transition:transform .16s ease,box-shadow .16s ease}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow);text-decoration:none}
.svc h3{color:var(--ink)}
.svc .more{color:var(--link);font-weight:750;font-size:.94rem;display:inline-flex;gap:.4em;align-items:center;margin-top:8px}
.svc:hover .more{gap:.7em}

/* tint + dark section variants */
.sec.tint{background:var(--tint)}
.sec.tint2{background:var(--tint2)}
.sec.sand{background:var(--sand)}
.sec.dark{background:var(--deep);color:#dfeef5}
.sec.dark h2,.sec.dark h3{color:#fff}
.sec.dark .eyebrow{color:#7fe0cf}
.sec.dark .lead{color:#bcd7e3}
.sec.grad{background:linear-gradient(120deg,var(--deep),var(--blue) 62%,var(--teal));color:#fff}
.sec.grad h2{color:#fff}

/* feature rows */
.feat{display:flex;gap:14px;align-items:flex-start}
.feat i{flex:0 0 auto;width:44px;height:44px;border-radius:11px;display:grid;place-items:center;background:var(--tint);color:var(--blue);font-size:1.1rem}
.sec.dark .feat i{background:rgba(255,255,255,.10);color:var(--teal)}
.feat h3{margin-bottom:.2em;font-size:1.08rem}
.feat p{font-size:.96rem;margin:0}

/* chips (coverage) */
.chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:6px}
.chip{display:inline-flex;align-items:center;gap:.45em;background:#fff;border:1px solid var(--line);border-radius:999px;padding:.5em .95em;font-size:.92rem;font-weight:650;color:var(--ink)}
.chip.link{border-color:#bfe3d9;background:var(--tint2);color:#0b5a4c}
.chip.link:hover{background:#d3f0e8;text-decoration:none}
.chip i{color:var(--teal);font-size:.78rem}

/* process steps */
.steps{counter-reset:s;display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px 22px}
.step::before{counter-increment:s;content:counter(s);position:absolute;top:-18px;left:22px;width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--teal));color:#fff;font-weight:800;display:grid;place-items:center;box-shadow:var(--shadow-sm)}
.step h3{margin-top:8px;font-size:1.06rem}
.step p{font-size:.95rem;margin:0}

/* reviews scaffold */
.rev{background:#fff;border:1px dashed var(--blue);border-radius:var(--radius);padding:22px}
.rev .q{color:var(--teal);font-size:1.4rem}
.rev p{font-style:italic;color:var(--muted)}
.rev .who{font-style:normal;font-weight:750;color:var(--ink);font-size:.92rem;margin-top:8px}

/* FAQ */
.faq{max-width:860px;margin:0 auto}
.faq details{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:12px;overflow:hidden}
.faq summary{cursor:pointer;padding:18px 20px;font-weight:750;color:var(--ink);list-style:none;display:flex;justify-content:space-between;gap:16px;align-items:center}
